[91288] = {id=91288,name="A Test of the Hunt",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,description="So, you want a Farstrider recommendation? We don't hand those out like festival ribbons. If you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper. No shortcuts, no excuses. Let's see if you've got the spine for it.",rewardGold=312800,rewardXP=11765,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245202,x=0.422,y=0.132,zoneID=15968}},ends={{npcID=245202,x=0.422,y=0.132,zoneID=15968}},coords={x=0.422,y=0.132,source="quest_giver",zoneID=15968},questType="standard"},
[91291] = {id=91291,name="A Test of Blood",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,description="Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. Only those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!",rewardGold=625600,rewardXP=14705,rewardCurrencies={{id=3316,amount=20},{id=3365,amount=100}},starts={{npcID=245200,x=0.428,y=0.138,zoneID=15968}},ends={{npcID=245200,x=0.428,y=0.138,zoneID=15968}},coords={x=0.428,y=0.138,source="quest_giver",zoneID=15968},questType="standard"},
[91292] = {id=91292,name="A Test of the Arcane",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,description="Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane. Go to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation. Should you fail, don't bother returning. My time is too valuable for such trivial matters.",rewardGold=162600,rewardXP=5885,rewardCurrencies={{id=3316,amount=10},{id=3365,amount=50}},starts={{npcID=245201,x=0.432,y=0.146,zoneID=15968}},ends={{npcID=245201,x=0.432,y=0.146,zoneID=15968}},coords={x=0.432,y=0.146,source="quest_giver",zoneID=15968},questType="standard"},
